UPDATE t_rca_hypothesis
SET merged_into_id = (
  SELECT id FROM (
    SELECT h2.id AS id FROM t_rca_hypothesis h2
    WHERE h2.task_id = #{taskId} AND h2.hypothesis_code = #{mergedIntoCode}
    ORDER BY h2.revision DESC LIMIT 1
  ) AS target
)
WHERE task_id = #{taskId} AND hypothesis_code = #{hypothesisCode}

